import type { RoleEvidence } from "./measurement-types.js";

/** Content-aware evidence that a file was produced by a tool. A header is self-declared; line statistics are structural. */
export interface ContentDecision { role: "generated"; evidence: RoleEvidence; }

const BANNER_WINDOW_LINES = 10;

/**
 * Generator banners. "DO NOT EDIT" and the tag `@generated` are the conventions of protoc, Go, Facebook tooling and most others.
 * The two tags count only at the start of a comment, as the line-cap exemption reads them: a comment that merely names the tag,
 * such as this one, is not a header.
 */
const BANNERS: readonly RegExp[] = [
	/^@generated\b/,
	/^@codegen-data\b/,
	/(?<![`"'])\bDO NOT EDIT\b(?![.!]?[`"'])/,
	/\bdo not edit (?:this|by hand|manually|directly)\b/i,
	/\bcode generated by\b/i,
	/\b(?:this|the) file (?:was|is|has been) (?:automatically |auto-?)?generated\b/i,
	/^(?:auto-?generated|automatically generated|generated)\b\s*(?:by|from|with|file|code)\b/i,
	/\bauto-?generated (?:by|from)\b/i,
	// OpenAPI Generator writes "NOTE: This class is auto generated by OpenAPI Generator", "Do not edit the class manually." and
	// "Generated by OpenAPI Generator" (a docstring in Python, a block comment in TypeScript); orval and others write "Do not edit manually".
	/\bauto generated by\b/i,
	/\bdo not edit the class manually\b/i,
	/^generated by (?:the )?(?:openapi|swagger) generator\b/i,
];

interface CommentScan { text: string | null; inBlock: boolean; }

/** The comment text of one line, or null for code. Tracks a block comment across lines. */
function commentText(line: string, inBlock: boolean): CommentScan {
	const t = line.trim();
	if (inBlock) return { text: t.replace(/^\*+\s?/, ""), inBlock: !t.includes("*/") };
	if (t.startsWith("/*")) return { text: t.slice(2), inBlock: !t.includes("*/", 2) };
	if (t.startsWith("//")) return { text: t.replace(/^\/\/[!/]?\s*/, ""), inBlock: false };
	if (t.startsWith("#") && !t.startsWith("#!")) return { text: t.replace(/^#+\s*/, ""), inBlock: false };
	if (t.startsWith("<!--")) return { text: t.slice(4), inBlock: false };
	return { text: null, inBlock: false };
}

function bannerIn(text: string): string | null {
	for (const pattern of BANNERS) {
		const found = pattern.exec(text);
		if (found !== null) return found[0].trim();
	}
	return null;
}

/**
 * A generator banner in a comment of the first lines. This is the weakest evidence: the file declares itself, and an agent
 * can write the header. Reports must keep these separate from structural evidence.
 */
export function markerEvidence(content: string): RoleEvidence | null {
	const lines = content.split("\n", HEAD_SCAN_LINES);
	let inBlock = false, docQuote: string | null = null, codeSeen = false;
	for (const [index, line] of lines.entries()) {
		const doc = docstringText(line, docQuote, codeSeen || index >= DOCSTRING_OPEN_LINES);
		// Past the first lines only a module docstring that opened early may still be read (a license comment pushes it down).
		if (index >= BANNER_WINDOW_LINES && doc.quote === null && doc.text === null) break;
		docQuote = doc.quote;
		const scan: CommentScan = doc.text !== null ? { text: doc.text, inBlock } : commentText(line, inBlock);
		inBlock = scan.inBlock;
		if (scan.text === null && doc.quote === null && line.trim() !== "") codeSeen = true;
		const banner = scan.text === null ? null : bannerIn(scan.text.trim());
		if (banner !== null) return { kind: "marker", detail: `line ${index + 1}: ${banner}` };
	}
	return null;
}

/**
 * Strict generator banners for the HEADER rule: no start-anchored `generated code|file` (prose such as "a few dozen lines of generated code"
 * matched it in a real file), and `@codegen-data` is this repository's own carrier tag, not a generator's.
 */
const HEADER_BANNERS: readonly RegExp[] = [
	/^@generated\b/,
	/(?<![`"'])\bDO NOT EDIT\b(?![.!]?[`"'])/,
	/\bdo not edit (?:this|by hand|manually|directly)\b/i,
	/\bdo not edit the class manually\b/i,
	/\bcode generated by\b/i,
	/\b(?:this|the) (?:file|code|class) (?:was|is|has been) (?:automatically |auto-?)?generated\b/i,
	/^(?:auto-?generated|automatically generated|generated) (?:by|from|with)\b/i,
	/\bauto[- ]?generated (?:by|from)\b/i,
];
const HEADER_SCAN_LINES = 60;
const C_DIRECTIVE = /^#\s*(?:include|define|ifndef|ifdef|if|else|elif|endif|pragma|undef|error|import|line)\b/;

/**
 * A strict generator banner in the LEADING comment block: after an optional shebang, blanks, an encoding line, a license block and a
 * Python module docstring, before the first code statement. A banner anywhere else (a comment above one import, a vendored header that
 * mentions generated files in a later block, prose in a doc comment) gives nothing. This is MEASUREMENT evidence only (the population
 * of metrics, score, deadcode and verify's set-aside). The per-edit gates use `isGeneratedFile` in `harness/checks/shared-generated-and-suppression.ts`,
 * a separate function that this one never replaces; a test pins both.
 */
export function headerBannerEvidence(content: string): RoleEvidence | null {
	let inBlock = false, docQuote: string | null = null;
	for (const [index, line] of content.split("\n", HEADER_SCAN_LINES).entries()) {
		if (line.trim() === "" || (index === 0 && line.startsWith("#!"))) continue;
		if (docQuote === null && !inBlock && C_DIRECTIVE.test(line.trim())) return null;
		const doc = docstringText(line, docQuote, false);
		docQuote = doc.quote;
		const scan: CommentScan = doc.text !== null ? { text: doc.text, inBlock } : commentText(line, inBlock);
		if (scan.text === null) return null;
		inBlock = scan.inBlock;
		const text = scan.text.trim(), hit = HEADER_BANNERS.map((pattern) => pattern.exec(text)).find((found) => found !== null);
		if (hit) return { kind: "marker", detail: `line ${index + 1}: ${hit[0].trim()} (header)` };
	}
	return null;
}

const HEAD_SCAN_LINES = 40;
const DOCSTRING_OPEN_LINES = 20;

/**
 * The text of a Python module docstring line (OpenAPI Generator puts its banner there), or null. Only a docstring that opens before any
 * code counts: a triple-quoted string deeper in a file is a string literal, not a header.
 */
function docstringText(line: string, quote: string | null, codeSeen: boolean): { text: string | null; quote: string | null } {
	const t = line.trim();
	if (quote !== null) return t.includes(quote) ? { text: t.replace(quote, ""), quote: null } : { text: t, quote };
	const opened = codeSeen ? null : /^(?:[rRuU])?("""|''')(.*)$/.exec(t);
	if (opened === null || opened[1] === undefined) return { text: null, quote: null };
	const rest = opened[2] ?? "";
	return rest.includes(opened[1]) ? { text: rest.replace(opened[1], ""), quote: null } : { text: rest, quote: opened[1] };
}

/**
 * Minified or bundled text, from line statistics (one pass, no string or comment parsing): mean line length >= 400 chars,
 * space and tab share <= 0.065, `(` `)` share >= 0.01, `<` share <= 0.01, and no NUL byte.
 * Code that a bundler minified keeps its calls and loses its whitespace; a data table, a base64 string, minified JSON and an SVG
 * export have almost no parentheses (an Inkscape SVG has many `;` in style attributes, so semicolons are not counted); SVG and HTML
 * markup have many `<`; prose and hand-written code keep their spaces; a NUL byte means binary.
 * A hand-written file consisting of a long sequence of calls can also match this heuristic.
 */
export const SHAPE_MIN_CHARS = 10_000;
const SHAPE_MIN_MEAN_LINE = 400;
const SHAPE_MAX_SPACE_SHARE = 0.065;
const SHAPE_MIN_PAREN_SHARE = 0.01;
const SHAPE_MAX_MARKUP_SHARE = 0.01;

const OTHER = 0, NEWLINE = 1, SPACE = 2, PAREN = 3, MARKUP = 4, NUL = 5;
const CHAR_CLASS = new Uint8Array(128);
for (const [code, kind] of [[10, NEWLINE], [32, SPACE], [9, SPACE], [40, PAREN], [41, PAREN], [60, MARKUP], [0, NUL]] as const) CHAR_CLASS[code] = kind;

interface ShapeStatistics { mean: number; spaceShare: number; parenShare: number; markupShare: number; }

/** Line and character-class statistics of a text, or null for binary content (a NUL byte). */
function shapeStatistics(content: string): ShapeStatistics | null {
	const counts = [0, 0, 0, 0, 0, 0];
	for (let at = 0; at < content.length; at++) {
		const code = content.charCodeAt(at);
		const kind = code < 128 ? CHAR_CLASS[code] ?? OTHER : OTHER;
		counts[kind] = (counts[kind] ?? 0) + 1;
	}
	if ((counts[NUL] ?? 0) > 0) return null;
	const share = (kind: number): number => (counts[kind] ?? 0) / content.length;
	return { mean: content.length / ((counts[NEWLINE] ?? 0) + 1), spaceShare: share(SPACE), parenShare: share(PAREN), markupShare: share(MARKUP) };
}

export function shapeEvidence(content: string): RoleEvidence | null {
	if (content.length < SHAPE_MIN_CHARS) return null;
	const stats = shapeStatistics(content);
	if (stats === null || stats.mean < SHAPE_MIN_MEAN_LINE || stats.spaceShare > SHAPE_MAX_SPACE_SHARE) return null;
	if (stats.parenShare < SHAPE_MIN_PAREN_SHARE || stats.markupShare > SHAPE_MAX_MARKUP_SHARE) return null;
	return { kind: "shape", detail: `mean line ${stats.mean.toFixed(1)} chars, space share ${stats.spaceShare.toFixed(3)}, () share ${stats.parenShare.toFixed(3)}` };
}

/**
 * Minified shape, or a strict generator banner in the leading comment block (`headerBannerEvidence`), sets a file aside as generated in
 * the measurement population. Any other banner match (loose wording, a later position) only labels the file (`markerEvidence`, see
 * `inventory-refine.ts`). The per-edit gates do not call this: their exemption is `isGeneratedFile`.
 */
export function classifyByContent(content: string): ContentDecision | null {
	const evidence = shapeEvidence(content) ?? headerBannerEvidence(content);
	return evidence === null ? null : { role: "generated", evidence };
}
